import{z as A,x as p,o as e,c as B,q as r,j as n,D as E,d as i,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"设计规则的起源","description":"","frontmatter":{"title":"设计规则的起源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/design-rule-origin.md","filePath":"litho/design-rule-origin.md","lastUpdated":1791063341000}'),d={name:"litho/design-rule-origin.md"};function D(h,a,m,C,c,f){const o=p("Mermaid");return e(),B("div",null,[a[2]||(a[2]=r('<h1 id="设计规则的起源" tabindex="-1">设计规则的起源 <a class="header-anchor" href="#设计规则的起源" aria-label="Permalink to &quot;设计规则的起源&quot;">​</a></h1><div class="epigraph"><p>设计规则不是从瑞利公式抄下来的整数；它们是成像、套刻、刻蚀、电学与良率谈出来的可交货集合，写进手册之后才看起来像几何。</p><footer>—— 对照 Levinson 对设计规则与工艺能力的讨论；DTCO 把规则当作协同输出</footer></div><p><a href="/litho/decomposition-coloring-conflict">上一课</a>把不可染色写成硬失败。缺口是回溯：手册里最小间隔、最小宽度、via 覆盖、密度窗，最初是哪一截物理不够用。<a href="/litho/dtco-patterning">DTCO</a> 已说规则是协同输出；本课钉起源清单，供后课把面积、轨道、SRAM 读成规则的后果。最小面积与 tip-to-tip 的专项，留给<a href="/litho/min-area-tip-to-tip">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>瑞利 \\(CD = k_1\\lambda/\\mathrm{NA}\\) 只给节距量级。真实规则还包括：掩模可写（MRC）、胶塌缩与随机桥断、刻蚀 ARDE、CMP 密度、对准标记禁区、电学漏电与可靠性间距。每一条「min space = x nm」都是某一失效模式的代理，而不是光学分辨率的别名。</p><p><span class="marginnote">术语翻译：设计规则就是把「某种物理要出事」翻译成一条几何下限的手段——「min space」名义上是两条线的最小间距，实际是光学旁瓣、套刻误差、刻蚀负载、电学漏电这几笔账各留出的余量取了最大值。读规则先问一句：它在替哪种失效模式挡枪？</span></p><p>缺口是<strong>把规则读成失效模式</strong>，不是从第一性原理重讲成像。<a href="/litho/overlay-budget">套刻预算</a> 已经分解位置误差；via 覆盖规则有一截就是这笔预算的几何化。把规则当神圣整数，LFD 无法谈判；把规则当随便可破，LRC 失门。</p><h3 id="规则是冻结的窗口" tabindex="-1">规则是冻结的窗口 <a class="header-anchor" href="#规则是冻结的窗口" aria-label="Permalink to &quot;规则是冻结的窗口&quot;">​</a></h3><p>工艺窗随胶、光源、腔体漂。规则版本必须与 OPC 模型、刻蚀核、分解选项同发。节点中期换 EUV 单次，旧双重规则应整段退休，而不是叠床架屋。起源课的用处是：改一条规则时知道要重开哪一扇窗。</p><p><span class="marginnote">同一数字可能同时服务光学与可靠性。收紧「只为了好印」可能在电学上无意义，或反过来。改规则要声明主失效。</span></p><p><span class="marginnote">直觉类比：规则版本像航班时刻表与机场跑道同时翻修——时刻表（规则）必须改成新跑道（OPC 模型、刻蚀核、分解选项）落得了地的样子，且两边同一天生效。旧表配新跑道、或新表配旧跑道，都会出现「完全合法却印不出来」的图形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把手册条款映射到来源：光学/PV-band、分解/着色、套刻/覆盖、刻蚀/密度、CMP、可靠性、可制造性（填充、狭缝均匀）。每条附：计量如何验证、LRC 如何检查、例外是否存在（SRAM 常有自己的规则族）。与 <a href="/litho/litho-process-flow">光刻流程</a> 的关系：规则是流程能力的接口，不是流程本身。</p><p>起源清楚后，LFD 才知道该改库还是该改工艺。</p><p>手册修订走变更控制：改一条 min space，要列出受影响的 OPC 核、分解选项、PWQ 矩阵和电学可靠性条款。Levinson 把设计规则写成工艺能力的接口；本课要求接口变更有追溯，而不是在邮件里改一个整数。</p>',15)),(e(),n(s,null,{default:E(()=>[l(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%8F%90%E6%A1%88%3A%20%E6%94%B6%E7%B4%A7%20min%20space%22%5D%20--%3E%20W%7B%22%E4%B8%BB%E5%A4%B1%E6%95%88%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20W%20--%20%22%E5%85%89%E5%AD%A6%E5%8F%AF%E5%8D%B0%22%20--%3E%20O%5B%22%E9%87%8D%E8%B7%91%20PV-band%20%E4%B8%8E%20OPC%20%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20W%20--%20%22%E5%A5%97%E5%88%BB%E8%A6%86%E7%9B%96%22%20--%3E%20V%5B%22%E9%87%8D%E6%9F%A5%20overlay%20%E9%A2%84%E7%AE%97%E4%B8%8E%20via%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20W%20--%20%22%E7%94%B5%E5%AD%A6%E5%8F%AF%E9%9D%A0%22%20--%3E%20R%5B%22%E9%87%8D%E6%9F%A5%E6%BC%8F%E7%94%B5%E4%B8%8E%E5%8F%AF%E9%9D%A0%E6%80%A7%E9%97%B4%E8%B7%9D%22%5D%0A%20%20O%20--%3E%20M%5B%22%E5%88%97%E5%87%BA%E5%8F%97%E5%BD%B1%E5%93%8D%E7%9A%84%20OPC%20%E6%A0%B8%22%5D%0A%20%20V%20--%3E%20M%0A%20%20R%20--%3E%20M%0A%20%20M%20--%3E%20PW%5B%22%E6%9B%B4%E6%96%B0%20PWQ%20%E7%9F%A9%E9%98%B5%E4%B8%8E%20LRC%20%E6%A3%80%E6%9F%A5%22%5D%0A%20%20PW%20--%3E%20REL%5B%22%E4%B8%8E%E8%A7%84%E5%88%99%E7%89%88%E6%9C%AC%E5%90%8C%E5%8F%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"光学给出可印节距与二维禁区；套刻把「不同层之间」变成覆盖与 tip 规则；刻蚀把密度变成填充规则；随机把稀疏孔的面积规则收得比均值 CD 更严。设计规则检查是这些物理在多边形上的投影。投影有信息损失：合法图形仍可能是热点，故需要 LRC；热点合法化又可能倒逼加规则。",-1)),(e(),n(s,null,{default:E(()=>[l(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E5%85%89%E5%AD%A6%20%E5%A5%97%E5%88%BB%20%E5%88%BB%E8%9A%80%20%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20DR%5B%22%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20DR%20--%3E%20DRC%5B%22DRC%20%E5%87%A0%E4%BD%95%E9%97%A8%22%5D%0A%20%20DR%20--%3E%20LRC%5B%22LRC%20%E6%A8%A1%E5%9E%8B%E9%97%A8%22%5D%0A%20%20FAIL%5B%22%E7%A1%85%E4%B8%8A%E5%A4%B1%E6%95%88%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%E6%9D%A1%E6%AC%BE%E6%88%96%E6%94%B6%E7%B4%A7%22%5D%0A%20%20NEW%20--%3E%20DR%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：初学者容易以为 DRC 通过就万事大吉。DRC 只检查多边形几何合不合法，不保证印得出来——真正的桥连热点可能完全合法。所以先进工艺还要跑 LRC（基于模型的可印性检查）：几何合法是及格线，不是保证书。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写限价簿或 Transformer。不把某代工厂未公开的规则数值表当作文献。规则起源随节点变，历史数字不可当现节点规格。</p><p>后课默认：读规则先问失效模式。下一课专攻面积与 tip-to-tip——二维图形化最常被光学和套刻同时咬的两条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设计规则是多物理失效模式的几何代理，不是瑞利公式的整数翻版。</li><li>版本与模型、分解、腔体同发。</li><li>合法不等于可印；LRC 补投影损失。</li><li>出处：Levinson《Principles of Lithography》；DTCO 与设计规则公开论述。</li></ul>',6))])}const _=A(d,[["render",D]]);export{P as __pageData,_ as default};
